"""Tests for vendorsync.store.Store."""

import os
import tempfile
import unittest

from vendorsync.store import Store


class TestStore(unittest.TestCase):
    """Unit tests for the Store class."""

    def _fresh_path(self) -> str:
        f = tempfile.NamedTemporaryFile(delete=False, suffix=".db")
        f.close()
        return f.name

    def tearDown(self):
        # Clean up any leftover temp db files from this test run
        pass

    def _cleanup(self, path: str):
        if os.path.exists(path):
            os.remove(path)

    def test_empty_db_creates_tables(self):
        path = self._fresh_path()
        try:
            store = Store(path)
            self.assertEqual(store.count(), 0)
        finally:
            self._cleanup(path)

    def test_upsert_no_duplicates(self):
        path = self._fresh_path()
        try:
            store = Store(path)

            payments = [
                {
                    "id": f"pay_{i}",
                    "amount_minor": 100 + i,
                    "currency": "USD",
                    "created_at": "2025-01-01T00:00:00Z",
                    "status": "succeeded",
                }
                for i in range(10)
            ]

            inserted_first = store.upsert_many(payments)
            self.assertEqual(inserted_first, 10)

            inserted_second = store.upsert_many(payments)
            self.assertEqual(inserted_second, 0)

            self.assertEqual(store.count(), 10)
        finally:
            self._cleanup(path)

